<?php

namespace App\Services;

use App\Models\User;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;

class UserCreationService
{
    /**
     * Create a regular Concord user account.
     *
     * The initial password is generated by IAM and returned
     * to the caller once. Only its hash is stored.
     *
     * @return array{user: User, initial_password: string}
     */
    public function create(array $attributes): array
    {
        $username = trim($attributes['username']);
        $email = strtolower(trim($attributes['email']));
        $displayName = trim($attributes['display_name']);

        if (User::query()->where('username', $username)->exists()) {
            throw ValidationException::withMessages([
                'username' => ['This username is already taken.'],
            ]);
        }

        if (User::query()->where('email', $email)->exists()) {
            throw ValidationException::withMessages([
                'email' => ['This email address is already registered.'],
            ]);
        }

        $initialPassword = Str::password(16);

        $user = DB::transaction(function () use (
            $username,
            $email,
            $displayName,
            $initialPassword
        ) {
            return User::query()->create([
                'username' => $username,
                'email' => $email,
                'display_name' => $displayName,
                'password' => Hash::make($initialPassword),
                'status' => 'active',
                'is_it_admin' => false,
            ]);
        });

        return [
            'user' => $user,
            'initial_password' => $initialPassword,
        ];
    }
}
